Path('frontend/src/components/CustomerDebtConsolidationPanel.jsx').write_text('import { useEffect, useMemo, useState } from "react";\n\nimport axiosClient from "../api/axiosClient";\nimport CustomerDebtPrintPanel from "./CustomerDebtPrintPanel";\nimport { formatBusinessDate, formatBusinessDateTime } from "../utils/businessDate";\nimport "../styles/customerDebtConsolidation.css";\n\nfunction formatMoney(value) {\n  return `GHS ${Number(value || 0).toLocaleString("en-GB", {\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  })}`;\n}\n\nfunction statusLabel(value) {\n  const status = String(value || "").toLowerCase();\n  if (status === "paid") return "Paid";\n  if (status === "partial") return "Partial";\n  return "Unpaid";\n}\n\nexport default function CustomerDebtConsolidationPanel({\n  currentStoreCode = "STORE",\n  currentStoreName = "Selected Store",\n  userRole = "",\n  onRecordPayment,\n  onRefresh,\n}) {\n  const [customers, setCustomers] = useState([]);\n  const [summary, setSummary] = useState(null);\n  const [unlinked, setUnlinked] = useState(null);\n  const [search, setSearch] = useState("");\n  const [loading, setLoading] = useState(false);\n  const [selectedCustomer, setSelectedCustomer] = useState(null);\n  const [detailLoading, setDetailLoading] = useState(false);\n  const [mergeOpen, setMergeOpen] = useState(false);\n  const [masterCustomerId, setMasterCustomerId] = useState("");\n  const [sourceCustomerIds, setSourceCustomerIds] = useState([]);\n  const [mergeReason, setMergeReason] = useState("");\n  const [mergeConfirmation, setMergeConfirmation] = useState("");\n  const [merging, setMerging] = useState(false);\n  const [message, setMessage] = useState("");\n  const [error, setError] = useState("");\n\n  const canMerge = ["admin", "manager"].includes(\n    String(userRole || "").toLowerCase()\n  );\n\n  async function loadCustomers() {\n    setLoading(true);\n    setError("");\n\n    try {\n      const response = await axiosClient.get("/debt-customers");\n      setCustomers(response.data.customers || []);\n      setSummary(response.data.summary || null);\n      setUnlinked(response.data.unlinked || null);\n    } catch (requestError) {\n      setError(\n        requestError.response?.data?.message ||\n          "Could not load consolidated customer debts."\n      );\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  useEffect(() => {\n    loadCustomers();\n  }, []);\n\n  const filteredCustomers = useMemo(() => {\n    const term = search.trim().toLowerCase();\n    if (!term) return customers;\n\n    return customers.filter((customer) =>\n      [\n        customer.customer_name,\n        customer.customer_phone,\n        customer.customer_location,\n      ]\n        .filter(Boolean)\n        .some((value) => String(value).toLowerCase().includes(term))\n    );\n  }, [customers, search]);\n\n  async function openCustomer(customerId) {\n    setDetailLoading(true);\n    setError("");\n\n    try {\n      const response = await axiosClient.get(`/debt-customers/${customerId}`);\n      setSelectedCustomer(response.data);\n    } catch (requestError) {\n      setError(\n        requestError.response?.data?.message ||\n          "Could not load this customer\'s debt breakdown."\n      );\n    } finally {\n      setDetailLoading(false);\n    }\n  }\n\n  function toggleSource(customerId) {\n    const cleanId = String(customerId);\n    setSourceCustomerIds((current) =>\n      current.includes(cleanId)\n        ? current.filter((id) => id !== cleanId)\n        : [...current, cleanId]\n    );\n  }\n\n  function resetMergeForm() {\n    setMasterCustomerId("");\n    setSourceCustomerIds([]);\n    setMergeReason("");\n    setMergeConfirmation("");\n  }\n\n  async function mergeCustomers(event) {\n    event.preventDefault();\n    setMessage("");\n    setError("");\n\n    if (!masterCustomerId) {\n      setError("Choose the master customer record to keep.");\n      return;\n    }\n\n    const sources = sourceCustomerIds.filter(\n      (id) => String(id) !== String(masterCustomerId)\n    );\n\n    if (sources.length === 0) {\n      setError("Select at least one duplicate customer record.");\n      return;\n    }\n\n    setMerging(true);\n\n    try {\n      const response = await axiosClient.post("/debt-customers/merge", {\n        target_customer_id: Number(masterCustomerId),\n        source_customer_ids: sources.map(Number),\n        reason: mergeReason,\n        confirmation: mergeConfirmation,\n      });\n\n      setMessage(response.data.message || "Customer records merged successfully.");\n      resetMergeForm();\n      setMergeOpen(false);\n      setSelectedCustomer(null);\n      await loadCustomers();\n      if (typeof onRefresh === "function") {\n        await onRefresh();\n      }\n    } catch (requestError) {\n      setError(\n        requestError.response?.data?.message ||\n          "Could not merge the selected customer records."\n      );\n    } finally {\n      setMerging(false);\n    }\n  }\n\n  function handleRecordPayment(debt) {\n    if (typeof onRecordPayment === "function") {\n      onRecordPayment(debt);\n    }\n    setSelectedCustomer(null);\n  }\n\n  return (\n    <section className="customer-debt-consolidation">\n      <div className="customer-debt-consolidation-heading">\n        <div>\n          <p>Customer Debt Consolidation</p>\n          <h2>One customer, one clear debt overview</h2>\n          <span>\n            Every receipt and payment remains separate for audit, while the screen\n            combines the balances under the correct customer.\n          </span>\n        </div>\n\n        <div className="customer-debt-consolidation-actions">\n          <button type="button" onClick={loadCustomers} disabled={loading}>\n            {loading ? "Refreshing..." : "Refresh"}\n          </button>\n\n          {canMerge ? (\n            <button\n              type="button"\n              className="secondary-button"\n              onClick={() => {\n                setMergeOpen((current) => !current);\n                setError("");\n                setMessage("");\n              }}\n            >\n              {mergeOpen ? "Close Merge Tool" : "Merge Duplicate Customers"}\n            </button>\n          ) : null}\n        </div>\n      </div>\n\n      {message ? (\n        <div className="customer-debt-consolidation-message success">\n          {message}\n        </div>\n      ) : null}\n\n      {error ? (\n        <div className="customer-debt-consolidation-message error">{error}</div>\n      ) : null}\n\n      <div className="customer-debt-consolidation-metrics">\n        <div>\n          <span>Customers Owing</span>\n          <strong>{Number(summary?.customer_count || 0)}</strong>\n        </div>\n        <div>\n          <span>Active Debt Records</span>\n          <strong>{Number(summary?.active_debt_count || 0)}</strong>\n        </div>\n        <div>\n          <span>Outstanding</span>\n          <strong>{formatMoney(summary?.outstanding_balance)}</strong>\n        </div>\n        <div>\n          <span>Overdue Records</span>\n          <strong>{Number(summary?.overdue_debt_count || 0)}</strong>\n        </div>\n      </div>\n\n      {Number(unlinked?.debt_count || 0) > 0 ? (\n        <div className="customer-debt-consolidation-warning">\n          <strong>{unlinked.debt_count} older debt record(s) are not linked to a saved customer.</strong>\n          <span>\n            Outstanding unlinked amount: {formatMoney(unlinked.outstanding_balance)}.\n            These records remain visible in Individual Debt Records and are not\n            changed automatically.\n          </span>\n        </div>\n      ) : null}\n\n      {mergeOpen && canMerge ? (\n        <form className="customer-debt-merge-panel" onSubmit={mergeCustomers}>\n          <div>\n            <p>Controlled Customer Merge</p>\n            <h3>Choose the correct master customer</h3>\n            <span>\n              Duplicate customer identities will be removed after their sales,\n              debts and installment links are reassigned. Receipts, debt records,\n              items and payments are preserved.\n            </span>\n          </div>\n\n          <label>\n            <span>Master Customer to Keep</span>\n            <select\n              value={masterCustomerId}\n              onChange={(event) => {\n                setMasterCustomerId(event.target.value);\n                setSourceCustomerIds((current) =>\n                  current.filter((id) => id !== event.target.value)\n                );\n              }}\n            >\n              <option value="">Choose master customer</option>\n              {customers.map((customer) => (\n                <option key={customer.customer_id} value={customer.customer_id}>\n                  {customer.customer_name} — {customer.customer_phone || "No phone"} —{" "}\n                  {formatMoney(customer.outstanding_balance)}\n                </option>\n              ))}\n            </select>\n          </label>\n\n          <div className="customer-debt-merge-list">\n            <strong>Duplicate Customer Record(s) to Merge</strong>\n            <span>Select only records that belong to the same real customer.</span>\n\n            {customers\n              .filter(\n                (customer) =>\n                  String(customer.customer_id) !== String(masterCustomerId)\n              )\n              .map((customer) => (\n                <label key={customer.customer_id}>\n                  <input\n                    type="checkbox"\n                    checked={sourceCustomerIds.includes(\n                      String(customer.customer_id)\n                    )}\n                    onChange={() => toggleSource(customer.customer_id)}\n                  />\n                  <span>\n                    <strong>{customer.customer_name}</strong>\n                    <small>\n                      {customer.customer_phone || "No phone"} ·{" "}\n                      {customer.debt_count} debt record(s) ·{" "}\n                      {formatMoney(customer.outstanding_balance)}\n                    </small>\n                  </span>\n                </label>\n              ))}\n          </div>\n\n          <label>\n            <span>Reason for Merge</span>\n            <textarea\n              value={mergeReason}\n              onChange={(event) => setMergeReason(event.target.value)}\n              placeholder="Example: Same customer was entered several times before reusable customer search was introduced."\n            />\n          </label>\n\n          <label>\n            <span>Confirmation</span>\n            <input\n              value={mergeConfirmation}\n              onChange={(event) => setMergeConfirmation(event.target.value)}\n              placeholder="Type MERGE"\n              autoComplete="off"\n            />\n          </label>\n\n          <button type="submit" disabled={merging}>\n            {merging ? "Merging Safely..." : "Merge Selected Customers"}\n          </button>\n        </form>\n      ) : null}\n\n      <div className="customer-debt-consolidation-search">\n        <label htmlFor="customer-debt-search">Find Customer Debt</label>\n        <input\n          id="customer-debt-search"\n          type="search"\n          value={search}\n          onChange={(event) => setSearch(event.target.value)}\n          placeholder="Search by customer name, phone or location"\n        />\n      </div>\n\n      {detailLoading ? (\n        <div className="customer-debt-consolidation-loading">\n          Loading customer debt breakdown...\n        </div>\n      ) : null}\n\n      <div className="customer-debt-consolidation-list">\n        {filteredCustomers.length === 0 && !loading ? (\n          <div className="customer-debt-consolidation-empty">\n            No customer debt matches this search.\n          </div>\n        ) : null}\n\n        {filteredCustomers.map((customer) => (\n          <article\n            key={customer.customer_id}\n            className="customer-debt-consolidation-card"\n          >\n            <div className="customer-debt-consolidation-card-main">\n              <div>\n                <h3>{customer.customer_name}</h3>\n                <p>\n                  {customer.customer_phone || "No phone"} ·{" "}\n                  {customer.customer_location || "No location"}\n                </p>\n                <small>\n                  First debt: {formatBusinessDate(customer.first_debt_date)} · Last\n                  debt: {formatBusinessDate(customer.last_debt_date)}\n                </small>\n              </div>\n\n              <div className="customer-debt-consolidation-balance">\n                <span>Total Outstanding</span>\n                <strong>{formatMoney(customer.outstanding_balance)}</strong>\n                <small>\n                  {customer.active_debt_count} active of {customer.debt_count} debt\n                  record(s)\n                </small>\n              </div>\n            </div>\n\n            <div className="customer-debt-consolidation-card-grid">\n              <div>\n                <span>Total Owed</span>\n                <strong>{formatMoney(customer.total_owed)}</strong>\n              </div>\n              <div>\n                <span>Total Paid</span>\n                <strong>{formatMoney(customer.total_paid)}</strong>\n              </div>\n              <div>\n                <span>Next Due Date</span>\n                <strong>{formatBusinessDate(customer.next_due_date)}</strong>\n              </div>\n              <div>\n                <span>Overdue</span>\n                <strong>{Number(customer.overdue_count || 0)}</strong>\n              </div>\n            </div>\n\n            <button\n              type="button"\n              onClick={() => openCustomer(customer.customer_id)}\n            >\n              Open Full Debt Breakdown\n            </button>\n          </article>\n        ))}\n      </div>\n\n      {selectedCustomer ? (\n        <div className="modal-backdrop">\n          <div className="customer-debt-detail-modal">\n            <div className="customer-debt-detail-header">\n              <div>\n                <p>Customer Debt Account</p>\n                <h2>{selectedCustomer.customer?.name}</h2>\n                <span>\n                  {selectedCustomer.customer?.phone || "No phone"} ·{" "}\n                  {selectedCustomer.customer?.location || "No location"} ·{" "}\n                  {currentStoreCode} — {currentStoreName}\n                </span>\n              </div>\n\n              <button\n                type="button"\n                className="secondary-button"\n                onClick={() => setSelectedCustomer(null)}\n              >\n                Close\n              </button>\n            </div>\n\n            <div className="customer-debt-detail-summary">\n              <div>\n                <span>Debt Records</span>\n                <strong>{selectedCustomer.summary?.debt_count || 0}</strong>\n              </div>\n              <div>\n                <span>Total Owed</span>\n                <strong>{formatMoney(selectedCustomer.summary?.total_owed)}</strong>\n              </div>\n              <div>\n                <span>Total Paid</span>\n                <strong>{formatMoney(selectedCustomer.summary?.total_paid)}</strong>\n              </div>\n              <div>\n                <span>Outstanding</span>\n                <strong>\n                  {formatMoney(selectedCustomer.summary?.outstanding_balance)}\n                </strong>\n              </div>\n            </div>\n\n            <CustomerDebtPrintPanel\n              currentStoreCode={currentStoreCode}\n              preferredCustomer={{\n                customer_id: selectedCustomer.customer?.id,\n                customer_name: selectedCustomer.customer?.name,\n                customer_phone: selectedCustomer.customer?.phone,\n                name: selectedCustomer.customer?.name,\n                phone: selectedCustomer.customer?.phone,\n              }}\n              preferredCustomerId={selectedCustomer.customer?.id}\n              reportType="debt"\n            />\n\n            <div className="customer-debt-breakdown-list">\n              {(selectedCustomer.debts || []).map((debt) => (\n                <article key={debt.id} className="customer-debt-breakdown-card">\n                  <div className="customer-debt-breakdown-heading">\n                    <div>\n                      <p>Receipt {debt.receipt_number || "-"}</p>\n                      <h3>\n                        {formatMoney(debt.balance)} outstanding\n                      </h3>\n                      <span>\n                        Debt Date: {formatBusinessDate(debt.created_at)} · Due Date:{" "}\n                        {formatBusinessDate(debt.due_date)}\n                      </span>\n                    </div>\n\n                    <span className={`customer-debt-status ${String(debt.status || "").toLowerCase()}`}>\n                      {statusLabel(debt.status)}\n                    </span>\n                  </div>\n\n                  <div className="customer-debt-breakdown-metrics">\n                    <div>\n                      <span>Sale Total</span>\n                      <strong>{formatMoney(debt.sale_total || debt.amount_owed)}</strong>\n                    </div>\n                    <div>\n                      <span>Debt Owed</span>\n                      <strong>{formatMoney(debt.amount_owed)}</strong>\n                    </div>\n                    <div>\n                      <span>Paid</span>\n                      <strong>{formatMoney(debt.amount_paid)}</strong>\n                    </div>\n                    <div>\n                      <span>Payment Type</span>\n                      <strong>{String(debt.payment_type || "-").toUpperCase()}</strong>\n                    </div>\n                    <div>\n                      <span>Sold By</span>\n                      <strong>{debt.staff_name || "-"}</strong>\n                    </div>\n                    <div>\n                      <span>Sale Time</span>\n                      <strong>{formatBusinessDateTime(debt.sale_date)}</strong>\n                    </div>\n                  </div>\n\n                  <h4>Items Bought</h4>\n                  {(debt.items || []).length === 0 ? (\n                    <p className="customer-debt-breakdown-empty">\n                      No item breakdown is available for this older sale.\n                    </p>\n                  ) : (\n                    <div className="customer-debt-table-wrap">\n                      <table>\n                        <thead>\n                          <tr>\n                            <th>Item</th>\n                            <th>Qty</th>\n                            <th>Unit Price</th>\n                            <th>Line Total</th>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          {debt.items.map((item) => (\n                            <tr key={item.id}>\n                              <td>{item.product_name}</td>\n                              <td>{item.quantity}</td>\n                              <td>{formatMoney(item.unit_price)}</td>\n                              <td>{formatMoney(item.line_total)}</td>\n                            </tr>\n                          ))}\n                        </tbody>\n                      </table>\n                    </div>\n                  )}\n\n                  <h4>Payments on This Debt</h4>\n                  {(debt.payments || []).length === 0 ? (\n                    <p className="customer-debt-breakdown-empty">\n                      No separate debt payment has been recorded yet.\n                    </p>\n                  ) : (\n                    <div className="customer-debt-table-wrap">\n                      <table>\n                        <thead>\n                          <tr>\n                            <th>Date</th>\n                            <th>Amount</th>\n                            <th>Method</th>\n                            <th>Received By</th>\n                            <th>Notes</th>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          {debt.payments.map((payment) => (\n                            <tr key={payment.id}>\n                              <td>{formatBusinessDateTime(payment.paid_at)}</td>\n                              <td>{formatMoney(payment.amount)}</td>\n                              <td>{String(payment.payment_method || "-").toUpperCase()}</td>\n                              <td>{payment.received_by_name || "-"}</td>\n                              <td>{payment.notes || "-"}</td>\n                            </tr>\n                          ))}\n                        </tbody>\n                      </table>\n                    </div>\n                  )}\n\n                  {Number(debt.balance || 0) > 0 ? (\n                    <button\n                      type="button"\n                      onClick={() => handleRecordPayment(debt)}\n                    >\n                      Record Payment for This Receipt\n                    </button>\n                  ) : null}\n                </article>\n              ))}\n            </div>\n          </div>\n        </div>\n      ) : null}\n    </section>\n  );\n}\n', encoding='utf-8')
Path('frontend/src/styles/customerDebtConsolidation.css').parent.mkdir(parents=True, exist_ok=True)
Path('frontend/src/styles/customerDebtConsolidation.css').write_text('.customer-debt-consolidation {\n  margin: 18px 0;\n  padding: 20px;\n  border: 1px solid #d7dee8;\n  border-radius: 24px;\n  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);\n  box-shadow: 0 18px 46px rgba(15, 23, 42, 0.08);\n}\n\n.customer-debt-consolidation-heading,\n.customer-debt-detail-header,\n.customer-debt-breakdown-heading,\n.customer-debt-consolidation-card-main {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.customer-debt-consolidation-heading p,\n.customer-debt-detail-header p,\n.customer-debt-merge-panel > div > p,\n.customer-debt-breakdown-heading p {\n  margin: 0 0 4px;\n  color: #9a6700;\n  font-size: 0.72rem;\n  font-weight: 800;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n}\n\n.customer-debt-consolidation-heading h2,\n.customer-debt-detail-header h2,\n.customer-debt-merge-panel h3,\n.customer-debt-breakdown-heading h3 {\n  margin: 0;\n  color: #0f172a;\n}\n\n.customer-debt-consolidation-heading span,\n.customer-debt-detail-header span,\n.customer-debt-merge-panel > div > span,\n.customer-debt-breakdown-heading span {\n  display: block;\n  margin-top: 6px;\n  color: #64748b;\n  line-height: 1.5;\n}\n\n.customer-debt-consolidation-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.customer-debt-consolidation button,\n.customer-debt-detail-modal button,\n.customer-debt-merge-panel button {\n  min-height: 42px;\n  padding: 10px 14px;\n  border: 0;\n  border-radius: 10px;\n  background: #0b3760;\n  color: #ffffff;\n  cursor: pointer;\n  font-weight: 800;\n}\n\n.customer-debt-consolidation button.secondary-button,\n.customer-debt-detail-modal button.secondary-button {\n  border: 1px solid #cbd5e1;\n  background: #ffffff;\n  color: #0f172a;\n}\n\n.customer-debt-consolidation button:disabled {\n  cursor: wait;\n  opacity: 0.65;\n}\n\n.customer-debt-consolidation-message,\n.customer-debt-consolidation-warning,\n.customer-debt-consolidation-loading,\n.customer-debt-consolidation-empty {\n  margin-top: 14px;\n  padding: 12px 14px;\n  border-radius: 12px;\n  line-height: 1.5;\n}\n\n.customer-debt-consolidation-message.success {\n  border: 1px solid #a7d7c5;\n  background: #effaf5;\n  color: #0f5132;\n}\n\n.customer-debt-consolidation-message.error {\n  border: 1px solid #fecaca;\n  background: #fff1f2;\n  color: #9f1239;\n}\n\n.customer-debt-consolidation-warning {\n  display: grid;\n  gap: 4px;\n  border: 1px solid #fde68a;\n  background: #fffbeb;\n  color: #854d0e;\n}\n\n.customer-debt-consolidation-metrics,\n.customer-debt-detail-summary,\n.customer-debt-consolidation-card-grid,\n.customer-debt-breakdown-metrics {\n  display: grid;\n  gap: 10px;\n  margin-top: 16px;\n}\n\n.customer-debt-consolidation-metrics,\n.customer-debt-detail-summary {\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.customer-debt-consolidation-card-grid {\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n}\n\n.customer-debt-breakdown-metrics {\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n}\n\n.customer-debt-consolidation-metrics > div,\n.customer-debt-detail-summary > div,\n.customer-debt-consolidation-card-grid > div,\n.customer-debt-breakdown-metrics > div {\n  display: grid;\n  gap: 4px;\n  padding: 12px;\n  border: 1px solid #dbe3ec;\n  border-radius: 12px;\n  background: #ffffff;\n}\n\n.customer-debt-consolidation-metrics span,\n.customer-debt-detail-summary span,\n.customer-debt-consolidation-card-grid span,\n.customer-debt-breakdown-metrics span,\n.customer-debt-consolidation-balance span {\n  color: #64748b;\n  font-size: 0.75rem;\n}\n\n.customer-debt-consolidation-metrics strong,\n.customer-debt-detail-summary strong,\n.customer-debt-consolidation-card-grid strong,\n.customer-debt-breakdown-metrics strong {\n  color: #0f172a;\n  overflow-wrap: anywhere;\n}\n\n.customer-debt-consolidation-search {\n  display: grid;\n  gap: 6px;\n  margin-top: 16px;\n}\n\n.customer-debt-consolidation-search label,\n.customer-debt-merge-panel label > span {\n  color: #334155;\n  font-size: 0.78rem;\n  font-weight: 800;\n}\n\n.customer-debt-consolidation-search input,\n.customer-debt-merge-panel input,\n.customer-debt-merge-panel select,\n.customer-debt-merge-panel textarea {\n  width: 100%;\n  min-height: 42px;\n  padding: 10px 12px;\n  border: 1px solid #cbd5e1;\n  border-radius: 10px;\n  background: #ffffff;\n  color: #0f172a;\n}\n\n.customer-debt-merge-panel textarea {\n  min-height: 90px;\n  resize: vertical;\n}\n\n.customer-debt-consolidation-list {\n  display: grid;\n  gap: 12px;\n  margin-top: 14px;\n}\n\n.customer-debt-consolidation-card {\n  padding: 16px;\n  border: 1px solid #dbe3ec;\n  border-radius: 18px;\n  background: #ffffff;\n}\n\n.customer-debt-consolidation-card h3 {\n  margin: 0;\n  color: #0f172a;\n}\n\n.customer-debt-consolidation-card p {\n  margin: 5px 0;\n  color: #475569;\n}\n\n.customer-debt-consolidation-card small {\n  color: #64748b;\n  line-height: 1.45;\n}\n\n.customer-debt-consolidation-balance {\n  min-width: 190px;\n  padding: 12px;\n  border-radius: 14px;\n  background: #0b2f52;\n  color: #ffffff;\n  text-align: right;\n}\n\n.customer-debt-consolidation-balance strong,\n.customer-debt-consolidation-balance small {\n  display: block;\n}\n\n.customer-debt-consolidation-balance strong {\n  margin: 4px 0;\n  font-size: 1.15rem;\n}\n\n.customer-debt-consolidation-balance span,\n.customer-debt-consolidation-balance small {\n  color: #dbeafe;\n}\n\n.customer-debt-consolidation-card > button {\n  width: 100%;\n  margin-top: 12px;\n}\n\n.customer-debt-merge-panel {\n  display: grid;\n  gap: 14px;\n  margin-top: 16px;\n  padding: 16px;\n  border: 1px solid #f4d36a;\n  border-radius: 18px;\n  background: #fffdf5;\n}\n\n.customer-debt-merge-panel label {\n  display: grid;\n  gap: 6px;\n}\n\n.customer-debt-merge-list {\n  display: grid;\n  gap: 8px;\n  max-height: 320px;\n  overflow-y: auto;\n  padding: 12px;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: #ffffff;\n}\n\n.customer-debt-merge-list > span {\n  color: #64748b;\n  font-size: 0.76rem;\n}\n\n.customer-debt-merge-list label {\n  display: flex;\n  align-items: flex-start;\n  gap: 10px;\n  padding: 10px;\n  border: 1px solid #eef2f7;\n  border-radius: 10px;\n}\n\n.customer-debt-merge-list input {\n  width: auto;\n  min-height: 0;\n  margin-top: 3px;\n}\n\n.customer-debt-merge-list label > span {\n  display: grid;\n  gap: 3px;\n}\n\n.customer-debt-merge-list small {\n  color: #64748b;\n}\n\n.customer-debt-detail-modal {\n  width: min(1180px, calc(100vw - 30px));\n  max-height: calc(100vh - 30px);\n  overflow-y: auto;\n  padding: 20px;\n  border-radius: 22px;\n  background: #ffffff;\n  box-shadow: 0 30px 80px rgba(15, 23, 42, 0.35);\n}\n\n.customer-debt-breakdown-list {\n  display: grid;\n  gap: 14px;\n  margin-top: 16px;\n}\n\n.customer-debt-breakdown-card {\n  padding: 16px;\n  border: 1px solid #dbe3ec;\n  border-radius: 16px;\n  background: #f8fafc;\n}\n\n.customer-debt-breakdown-card h4 {\n  margin: 16px 0 8px;\n  color: #0f172a;\n}\n\n.customer-debt-status {\n  padding: 6px 10px;\n  border-radius: 999px;\n  font-size: 0.72rem;\n  font-weight: 800;\n}\n\n.customer-debt-status.unpaid {\n  background: #fee2e2;\n  color: #991b1b;\n}\n\n.customer-debt-status.partial {\n  background: #fef3c7;\n  color: #92400e;\n}\n\n.customer-debt-status.paid {\n  background: #dcfce7;\n  color: #166534;\n}\n\n.customer-debt-table-wrap {\n  overflow-x: auto;\n  border: 1px solid #e2e8f0;\n  border-radius: 12px;\n  background: #ffffff;\n}\n\n.customer-debt-table-wrap table {\n  width: 100%;\n  border-collapse: collapse;\n  min-width: 620px;\n}\n\n.customer-debt-table-wrap th,\n.customer-debt-table-wrap td {\n  padding: 10px;\n  border-bottom: 1px solid #eef2f7;\n  text-align: left;\n  font-size: 0.78rem;\n}\n\n.customer-debt-table-wrap th {\n  background: #f8fafc;\n  color: #334155;\n}\n\n.customer-debt-breakdown-empty {\n  margin: 0;\n  color: #64748b;\n}\n\n.debt-record-view-toggle {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n  margin: 16px 0;\n  padding: 12px 14px;\n  border: 1px solid #dbe3ec;\n  border-radius: 12px;\n  background: #ffffff;\n}\n\n.debt-record-view-toggle span {\n  color: #64748b;\n  font-size: 0.78rem;\n  line-height: 1.4;\n}\n\n.debt-record-view-toggle button {\n  flex: 0 0 auto;\n  min-height: 40px;\n  padding: 9px 13px;\n  border: 0;\n  border-radius: 10px;\n  background: #0b3760;\n  color: #ffffff;\n  cursor: pointer;\n  font-weight: 800;\n}\n\n@media (max-width: 900px) {\n  .customer-debt-consolidation-metrics,\n  .customer-debt-detail-summary,\n  .customer-debt-consolidation-card-grid,\n  .customer-debt-breakdown-metrics {\n    grid-template-columns: repeat(2, minmax(0, 1fr));\n  }\n}\n\n@media (max-width: 720px) {\n  .customer-debt-consolidation {\n    padding: 14px;\n    border-radius: 18px;\n  }\n\n  .customer-debt-consolidation-heading,\n  .customer-debt-detail-header,\n  .customer-debt-breakdown-heading,\n  .customer-debt-consolidation-card-main,\n  .debt-record-view-toggle {\n    align-items: stretch;\n    flex-direction: column;\n  }\n\n  .customer-debt-consolidation-actions,\n  .customer-debt-consolidation-actions button,\n  .customer-debt-detail-header button,\n  .customer-debt-breakdown-card > button,\n  .debt-record-view-toggle button {\n    width: 100%;\n  }\n\n  .customer-debt-consolidation-metrics,\n  .customer-debt-detail-summary,\n  .customer-debt-consolidation-card-grid,\n  .customer-debt-breakdown-metrics {\n    grid-template-columns: 1fr;\n  }\n\n  .customer-debt-consolidation-balance {\n    min-width: 0;\n    text-align: left;\n  }\n\n  .customer-debt-detail-modal {\n    width: calc(100vw - 16px);\n    max-height: calc(100vh - 16px);\n    padding: 14px;\n    border-radius: 16px;\n  }\n\n  .customer-debt-merge-list {\n    max-height: 240px;\n  }\n}\n', encoding='utf-8')
