Path('backend/tests/customerDebtConsolidation.test.js').write_text('const fs = require("fs");\nconst path = require("path");\nconst test = require("node:test");\nconst assert = require("node:assert/strict");\n\nconst ROOT = path.resolve(__dirname, "..", "..");\n\nfunction read(relativePath) {\n  return fs.readFileSync(path.join(ROOT, relativePath), "utf8");\n}\n\ntest("customer debt consolidation backend preserves records and merges identities", () => {\n  const route = read("backend/routes/customerDebtConsolidationRoutes.js");\n\n  assert.match(route, /router\\.get\\("\\/",/);\n  assert.match(route, /router\\.get\\("\\/:customerId",/);\n  assert.match(route, /requireRole\\("admin", "manager"\\)/);\n  assert.match(route, /UPDATE sales\\s+SET customer_id = \\?/);\n  assert.match(route, /UPDATE debts\\s+SET customer_id = \\?/);\n  assert.match(route, /UPDATE installment_agreements\\s+SET customer_id = \\?/);\n  assert.match(route, /DELETE FROM customers/);\n  assert.match(route, /MERGE_CUSTOMER_IDENTITIES/);\n  assert.match(route, /Original sales, receipts, debt records and payments were preserved/);\n});\n\ntest("customer debt breakdown contains receipts, items and payments", () => {\n  const route = read("backend/routes/customerDebtConsolidationRoutes.js");\n\n  assert.match(route, /s\\.receipt_number/);\n  assert.match(route, /FROM sale_items/);\n  assert.match(route, /FROM debt_payments/);\n  assert.match(route, /items: itemsBySale/);\n  assert.match(route, /payments: paymentsByDebt/);\n});\n\ntest("server exposes the consolidation route inside Spare Parts", () => {\n  const server = read("backend/server.js");\n\n  assert.match(\n    server,\n    /const customerDebtConsolidationRoutes = require\\("\\.\\/routes\\/customerDebtConsolidationRoutes"\\);/\n  );\n  assert.match(\n    server,\n    /app\\.use\\("\\/api\\/debt-customers", requireAuth, sparePartsBoundary, customerDebtConsolidationRoutes\\);/\n  );\n});\n\ntest("exact customer exports use customer id and retain print and downloads", () => {\n  const workspaceRoute = read("backend/routes/customerStatementWorkspaceRoutes.js");\n  const printPanel = read("frontend/src/components/CustomerDebtPrintPanel.jsx");\n\n  assert.match(workspaceRoute, /customerId = positiveId\\(req\\.query\\.customer_id\\)/);\n  assert.match(workspaceRoute, /appendCustomerIdFilter/);\n  assert.match(printPanel, /preferredCustomerId = null/);\n  assert.match(printPanel, /customer_id: filters\\.customer_id/);\n  assert.match(printPanel, /createReport\\("print"\\)/);\n  assert.match(printPanel, /createReport\\("pdf"\\)/);\n  assert.match(printPanel, /createReport\\("word"\\)/);\n  assert.match(printPanel, /createReport\\("excel"\\)/);\n});\n\ntest("Debts page defaults to customer consolidation with optional audit records", () => {\n  const page = read("frontend/src/pages/DebtsPage.jsx");\n  const component = read("frontend/src/components/CustomerDebtConsolidationPanel.jsx");\n  const css = read("frontend/src/styles/customerDebtConsolidation.css");\n\n  assert.match(page, /CustomerDebtConsolidationPanel/);\n  assert.match(page, /showIndividualDebts, setShowIndividualDebts/);\n  assert.match(component, /One customer, one clear debt overview/);\n  assert.match(component, /Open Full Debt Breakdown/);\n  assert.match(component, /Merge Duplicate Customers/);\n  assert.match(component, /CustomerDebtPrintPanel/);\n  assert.match(css, /@media \\(max-width: 720px\\)/);\n  assert.match(css, /\\.customer-debt-detail-modal/);\n});\n\ntest("service worker cache is advanced for the customer debt release", () => {\n  const serviceWorker = read("frontend/public/sw.js");\n  assert.match(serviceWorker, /chalin03-customer-debt-consolidation-v9/);\n});\n', encoding='utf-8')
update('backend/server.js', [('const debtRoutes = require("./routes/debtRoutes");\n', 'const debtRoutes = require("./routes/debtRoutes");\nconst customerDebtConsolidationRoutes = require("./routes/customerDebtConsolidationRoutes");\n', 'server route import'), ('      "/api/debts",\n', '      "/api/debts",\n      "/api/debt-customers",\n', 'api route list'), ('app.use("/api/debts", requireAuth, sparePartsBoundary, debtRoutes);\n', 'app.use("/api/debts", requireAuth, sparePartsBoundary, debtRoutes);\napp.use("/api/debt-customers", requireAuth, sparePartsBoundary, customerDebtConsolidationRoutes);\n', 'server route registration')])
update('frontend/src/pages/DebtsPage.jsx', [('import CustomerDebtPrintPanel from "../components/CustomerDebtPrintPanel";\n', 'import CustomerDebtPrintPanel from "../components/CustomerDebtPrintPanel";\nimport CustomerDebtConsolidationPanel from "../components/CustomerDebtConsolidationPanel";\n', 'Debts page component import'), ('  const [loading, setLoading] = useState(false);\n', '  const [loading, setLoading] = useState(false);\n  const [showIndividualDebts, setShowIndividualDebts] = useState(false);\n', 'Debts page individual records state'), ('      <CustomerDebtPrintPanel\n        currentStoreCode={currentStoreCode}\n        preferredCustomer={selectedDebt}\n        reportType="debt"\n      />\n', '      <CustomerDebtConsolidationPanel\n        currentStoreCode={currentStoreCode}\n        currentStoreName={currentStoreName}\n        userRole={user?.role}\n        onRecordPayment={preparePayment}\n        onRefresh={loadDebts}\n      />\n\n      <div className="debt-record-view-toggle">\n        <span>\n          The consolidated view keeps one card per customer. Open the individual\n          receipt-level records only when you need audit detail or a direct payment action.\n        </span>\n        <button\n          type="button"\n          onClick={() => setShowIndividualDebts((current) => !current)}\n        >\n          {showIndividualDebts ? "Hide Individual Debt Records" : "Show Individual Debt Records"}\n        </button>\n      </div>\n\n      <CustomerDebtPrintPanel\n        currentStoreCode={currentStoreCode}\n        preferredCustomer={selectedDebt}\n        reportType="debt"\n      />\n', 'Debts page consolidation insertion'), ('        <section style={styles.panelLarge}>\n', '        <section style={{ ...styles.panelLarge, display: showIndividualDebts ? "block" : "none" }}>\n', 'Debts page individual list visibility')])
update('frontend/src/components/CustomerDebtPrintPanel.jsx', [('export default function CustomerDebtPrintPanel({\n  currentStoreCode = "STORE",\n  preferredCustomer = null,\n  reportType = "debt",\n}) {\n', 'export default function CustomerDebtPrintPanel({\n  currentStoreCode = "STORE",\n  preferredCustomer = null,\n  preferredCustomerId = null,\n  reportType = "debt",\n}) {\n', 'print panel signature'), ('  const [filters, setFilters] = useState({\n    from: defaultFromDate(),\n    to: dateInputValue(new Date()),\n    customer: preferredSearch,\n    debt_status: "",\n  });\n', '  const [filters, setFilters] = useState({\n    from: defaultFromDate(),\n    to: dateInputValue(new Date()),\n    customer: preferredSearch,\n    customer_id: preferredCustomerId ? String(preferredCustomerId) : "",\n    debt_status: "",\n  });\n', 'print panel filters'), ('  useEffect(() => {\n    if (!preferredSearch) return;\n    setFilters((current) => ({ ...current, customer: preferredSearch }));\n  }, [preferredSearch]);\n', '  useEffect(() => {\n    if (!preferredSearch && !preferredCustomerId) return;\n    setFilters((current) => ({\n      ...current,\n      customer: preferredSearch || current.customer,\n      customer_id: preferredCustomerId ? String(preferredCustomerId) : "",\n    }));\n  }, [preferredSearch, preferredCustomerId]);\n', 'print panel preferred customer effect'), ('            customer: filters.customer.trim(),\n            debt_status: reportType === "debt" ? filters.debt_status : "",\n', '            customer: filters.customer.trim(),\n            customer_id: filters.customer_id,\n            debt_status: reportType === "debt" ? filters.debt_status : "",\n', 'print panel request params')])
update('backend/routes/customerStatementWorkspaceRoutes.js', [('  const customer = cleanText(req.query.customer || req.query.query, 160);\n  const debtStatus = cleanText(req.query.debt_status, 30).toLowerCase();\n', '  const customer = cleanText(req.query.customer || req.query.query, 160);\n  const customerId = positiveId(req.query.customer_id);\n  const debtStatus = cleanText(req.query.debt_status, 30).toLowerCase();\n', 'workspace customer id parsing'), ('  return { from, to, customer, debtStatus, reportType };\n', '  return { from, to, customer, customerId, debtStatus, reportType };\n', 'workspace filter return'), ('function appendCustomerFilter(sql, params, alias, filters) {\n  if (!filters.customer) return sql;\n', 'function appendCustomerIdFilter(sql, params, alias, filters) {\n  if (!filters.customerId) return sql;\n  params.push(filters.customerId);\n  return `${sql} AND ${alias}.customer_id = ?`;\n}\n\nfunction appendCustomerFilter(sql, params, alias, filters) {\n  if (filters.customerId || !filters.customer) return sql;\n', 'workspace exact customer filter helper'), ('  saleSql = appendDateFilter(saleSql, saleParams, "s", "created_at", filters);\n  saleSql = appendCustomerFilter(saleSql, saleParams, "s", filters);\n', '  saleSql = appendDateFilter(saleSql, saleParams, "s", "created_at", filters);\n  saleSql = appendCustomerIdFilter(saleSql, saleParams, "s", filters);\n  saleSql = appendCustomerFilter(saleSql, saleParams, "s", filters);\n', 'workspace sale customer id filter'), ('  debtSql = appendDateFilter(debtSql, debtParams, "d", "created_at", filters);\n  debtSql = appendCustomerFilter(debtSql, debtParams, "d", filters);\n', '  debtSql = appendDateFilter(debtSql, debtParams, "d", "created_at", filters);\n  debtSql = appendCustomerIdFilter(debtSql, debtParams, "d", filters);\n  debtSql = appendCustomerFilter(debtSql, debtParams, "d", filters);\n', 'workspace debt customer id filter'), ('  paymentSql = appendDateFilter(paymentSql, paymentParams, "dp", "paid_at", filters);\n  paymentSql = appendCustomerFilter(paymentSql, paymentParams, "d", filters);\n', '  paymentSql = appendDateFilter(paymentSql, paymentParams, "dp", "paid_at", filters);\n  paymentSql = appendCustomerIdFilter(paymentSql, paymentParams, "d", filters);\n  paymentSql = appendCustomerFilter(paymentSql, paymentParams, "d", filters);\n', 'workspace payment customer id filter')])
update('frontend/public/sw.js', [('const CACHE_NAME = "chalin03-debt-business-date-v8";', 'const CACHE_NAME = "chalin03-customer-debt-consolidation-v9";', 'service worker cache version')])
